G=load()

test = G['Test input']
print("=== TEST INPUT STRUCTURE ===")
print(f"Dimensions: {len(test)}x{len(test[0])}")
print("\nAll values:", sorted(set(val for row in test for val in row)))
print("Most common value per row:")
for i in range(9):
    vals = test[i]
    most_common = max(set(vals), key=vals.count)
    count = vals.count(most_common)
    print(f"  Row {i}: most common is {most_common} ({count} times)")

# Find rows that are NOT predominantly the dominant color (9)
print("\n\nRows that aren't mostly 9s:")
for i in range(9):
    nines = sum(1 for v in test[i] if v == 9)
    total = len(test[i])
    pct = nines / total * 100
    if pct < 100:
        print(f"  Row {i}: {nines}/{total} nines ({pct:.1f}%)")
        # Check if it has variety
        unique = set(test[i])
        print(f"           Values present: {sorted(unique)}")

